if($_SERVER['REQUEST_METHOD']==='POST' && isset($_POST['no_document_review'])){
    verify_csrf_or_abort();
    if ($isCoordinatorReviewer) { renderSweetAlertResponse('ไม่มีสิทธิ์ดำเนินการ','การยืนยันกรณีไม่มีใบตอบรับเป็นหน้าที่ของเจ้าหน้าที่สาขา','warning',$responseReviewReturnPage,403); }
    if (!responseNoDocumentReviewAvailable($pdo)) { renderSweetAlertResponse('ระบบยังไม่พร้อมใช้งาน','กรุณาติดตั้ง migration สำหรับการตรวจยืนยันกรณีไม่มีใบตอบรับก่อน','error',$responseReviewReturnPage,503); }
    $declarationId=(int)($_POST['response_declaration_id']??0); $action=(string)($_POST['no_document_action']??''); $note=trim((string)($_POST['review_note']??''));
    $map=['approve'=>'approved','revision'=>'revision_requested','not_accepted'=>'not_accepted'];
    if (!isset($map[$action]) || $note==='') { renderSweetAlertResponse('กรอกข้อมูลไม่ครบ','กรุณาระบุผลและบันทึกวิธีตรวจสอบก่อนบันทึก','warning',$responseReviewReturnPage,422); }
    $statement=$pdo->prepare('SELECT rdecl.internship_profile_id,rdecl.reported_result,rdecl.evidence_state,rdecl.updated_at,s.user_id,s.student_number,s.firstname,s.lastname
