    if (!$item || $item['evidence_state']!=='no_document') { renderSweetAlertResponse('ไม่พบรายการ','รายการไม่มีใบตอบรับไม่อยู่ในความรับผิดชอบของคุณ','error',$responseReviewReturnPage,404); }
    if ($action==='approve' && $item['reported_result']!=='accepted') { renderSweetAlertResponse('ยังยืนยันผ่านไม่ได้','ต้องให้นักศึกษาแจ้งว่าได้รับการตอบรับก่อน เจ้าหน้าที่จึงยืนยันเพื่อออกใบส่งตัวได้','warning',$responseReviewReturnPage,422); }
    $pdo->beginTransaction(); try {
