        createNotification($pdo,(int)$item['user_id'],null,'internship_no_document_review',$title,$message,'/Project/student/response_letter.php');
        $pdo->commit(); header('Location: response_letters.php?reviewed=1'); exit;
    } catch(Throwable $e) { if($pdo->inTransaction())$pdo->rollBack(); error_log('No-document review failed: '.$e->getMessage()); renderSweetAlertResponse('บันทึกผลไม่สำเร็จ','ระบบไม่สามารถบันทึกการตรวจยืนยันได้ กรุณาลองใหม่อีกครั้ง','error',$responseReviewReturnPage,500); }
}
if($_SERVER['REQUEST_METHOD']==='POST'){
    verify_csrf_or_abort(); $responseId=(int)($_POST['response_document_id']??0); $action=(string)($_POST['review_action']??''); $note=trim((string)($_POST['review_note']??''));
    $statusMap=['approve'=>'approved','revision'=>'revision_requested','not_accepted'=>'not_accepted']; if(!isset($statusMap[$action])){renderSweetAlertResponse('ผลการตรวจสอบไม่ถูกต้อง','กรุณาเลือกผลการตรวจสอบใหม่อีกครั้ง','warning',$responseReviewReturnPage,422);} if($action!=='approve'&&$note===''){renderSweetAlertResponse('กรุณาระบุรายละเอียดสำหรับนักศึกษา','โปรดบอกเหตุผลหรือจุดที่ต้องแก้ไขก่อนส่งผลการตรวจสอบ','warning',$responseReviewReturnPage,422);}
    $itemStmt=$pdo->prepare('SELECT rd.internship_profile_id,s.user_id,s.student_number,s.firstname,s.lastname FROM internship_response_document rd JOIN internship_profile ip ON ip.internship_profile_id=rd.internship_profile_id JOIN student s ON s.student_id=ip.student_id JOIN group_class g ON g.group_id=s.group_id WHERE rd.response_document_id=? AND g.department_id=? LIMIT 1'); $itemStmt->execute([$responseId,$staff['department_id']]); $item=$itemStmt->fetch(PDO::FETCH_ASSOC); if(!$item){renderSweetAlertResponse('ไม่พบหนังสือตอบรับ','ไม่พบหนังสือตอบรับในสาขาของคุณ','error',$responseReviewReturnPage,403);}
    $pdo->beginTransaction(); try {
        $reviewUpdate=$pdo->prepare('UPDATE internship_response_document SET review_status=?,review_note=?,reviewed_by=?,reviewed_at=NOW() WHERE response_document_id=? AND review_status="pending"');
        $reviewUpdate->execute([$statusMap[$action],$note?:null,$_SESSION['user_id'],$responseId]);
        if ($reviewUpdate->rowCount() !== 1) {
            throw new RuntimeException('รายการนี้ถูกดำเนินการแล้วโดยผู้ใช้อื่น');
        }
        $trackingStatus=$action==='approve'?'sent':($action==='not_accepted'?'not_sent':null);
        $pdo->prepare('INSERT INTO internship_tracking (internship_profile_id,response_status,employment_status,updated_by) VALUES (?,?,?,?) ON DUPLICATE KEY UPDATE response_status=VALUES(response_status),employment_status=VALUES(employment_status),updated_by=VALUES(updated_by)')->execute([(int)$item['internship_profile_id'],$trackingStatus,$action==='not_accepted'?'not_hired':'pending',$_SESSION['user_id']]);
        $reviewerLabel=$isCoordinatorReviewer?'อาจารย์ประสานงาน':'เจ้าหน้าที่';
        $title=$action==='approve'?'หนังสือตอบรับผ่านการตรวจสอบแล้ว':($action==='revision'?'กรุณาแก้ไขหนังสือตอบรับ':'สถานประกอบการไม่รับเข้าฝึกงาน');
        $message=$action==='approve'?$reviewerLabel.'ตรวจสอบหนังสือตอบรับแล้ว ระบบจะนำผลไปตรวจสอบความพร้อมสำหรับจัดทำใบส่งตัว':($action==='revision'?$reviewerLabel.'ส่งหนังสือตอบรับกลับให้แก้ไข: '.$note:'สถานประกอบการไม่รับเข้าฝึกงาน กรุณาเริ่มทำคำร้องสหกิจใหม่: '.$note);
        createNotification($pdo,(int)$item['user_id'],null,'internship_response_review',$title,$message,'/Project/student/response_letter.php');
        logActivity($pdo,(int)$_SESSION['user_id'],'internship_response_reviewed','ตรวจหนังสือตอบรับของ '.$item['student_number'].' เป็นสถานะ '.$statusMap[$action]);
        $pdo->commit(); header('Location: response_letters.php?reviewed=1');exit;
    }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();error_log('Response review failed: '.$e->getMessage());if($e instanceof RuntimeException && str_contains($e->getMessage(),'ดำเนินการแล้ว')){renderSweetAlertResponse('รายการถูกดำเนินการแล้ว','ผู้ใช้งานคนอื่นตรวจหนังสือตอบรับรายการนี้ไปก่อน กรุณาโหลดข้อมูลล่าสุด','info',$responseReviewReturnPage,409);}renderSweetAlertResponse('บันทึกผลไม่สำเร็จ','ระบบไม่สามารถบันทึกผลการตรวจสอบได้ กรุณาลองใหม่อีกครั้ง','error',$responseReviewReturnPage,500);}
}
$filter=(string)($_GET['status']??'pending'); $allowed=['pending','approved','revision_requested','not_accepted','all']; if(!in_array($filter,$allowed,true))$filter='pending'; $conditions=['g.department_id=?'];$params=[(int)$staff['department_id']];if($filter!=='all'){$conditions[]='rd.review_status=?';$params[]=$filter;}
$from=' FROM internship_response_document rd JOIN internship_profile ip ON ip.internship_profile_id=rd.internship_profile_id JOIN student s ON s.student_id=ip.student_id LEFT JOIN prefixes p ON p.prefix_id=s.prefix_id JOIN group_class g ON g.group_id=s.group_id LEFT JOIN employee e ON e.user_id=rd.reviewed_by WHERE '.implode(' AND ',$conditions);
$count=$pdo->prepare('SELECT COUNT(*)'.$from);$count->execute($params);$total=(int)$count->fetchColumn();$perPage=selected_per_page(10);$page=max(1,(int)($_GET['page']??1));$pages=max(1,(int)ceil($total/$perPage));$page=min($page,$pages);$offset=($page-1)*$perPage;
$list=$pdo->prepare('SELECT rd.*,ip.company_name,s.student_number,s.firstname,s.lastname,p.prefix_short,g.group_name,e.firstname reviewer_firstname,e.lastname reviewer_lastname'.$from.' ORDER BY FIELD(rd.review_status,"pending","revision_requested","approved","not_accepted"),rd.uploaded_at DESC LIMIT '.$perPage.' OFFSET '.$offset);$list->execute($params);$rows=$list->fetchAll(PDO::FETCH_ASSOC);
$noDocumentReviewJoin=responseNoDocumentReviewAvailable($pdo)?' LEFT JOIN internship_response_no_document_review ndr ON ndr.internship_profile_id=ip.internship_profile_id AND ndr.declaration_updated_at=rdecl.updated_at ':'';
$noDocumentReviewFields=responseNoDocumentReviewAvailable($pdo)?',ndr.review_status AS no_document_review_status,ndr.review_note AS no_document_review_note':'';
$followupStmt=$pdo->prepare('SELECT rdecl.response_declaration_id,ip.company_name,ip.recipient_name,ip.recipient_position,s.student_number,s.firstname,s.lastname,p.prefix_short,g.group_name,rdecl.reported_result,rdecl.evidence_state,rdecl.student_note,rdecl.declared_at'.$noDocumentReviewFields.'
    FROM internship_response_declaration rdecl
    JOIN internship_profile ip ON ip.internship_profile_id=rdecl.internship_profile_id
    JOIN student s ON s.student_id=ip.student_id
    LEFT JOIN prefixes p ON p.prefix_id=s.prefix_id
    JOIN group_class g ON g.group_id=s.group_id
    LEFT JOIN internship_response_document rd ON rd.internship_profile_id=ip.internship_profile_id '.$noDocumentReviewJoin.'
    WHERE g.department_id=? AND rd.response_document_id IS NULL
      AND rdecl.evidence_state IN ("no_document","awaiting_result")
    ORDER BY rdecl.updated_at DESC LIMIT 50');
$followupStmt->execute([(int)$staff['department_id']]);
$followups=$followupStmt->fetchAll(PDO::FETCH_ASSOC);
$pageHeading='ตรวจหนังสือตอบรับ';$staff_name=trim($staff['firstname'].' '.$staff['lastname']);$document_count=$total;function h($v):string{return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}$labels=['pending'=>'รอตรวจสอบ','approved'=>'ตรวจสอบผ่าน','revision_requested'=>'ส่งกลับแก้ไข','not_accepted'=>'ไม่รับเข้าฝึกงาน'];$classes=['pending'=>'bg-amber-100 text-amber-800','approved'=>'bg-emerald-100 text-emerald-800','revision_requested'=>'bg-red-100 text-red-700','not_accepted'=>'bg-slate-200 text-slate-700'];
