<?php if($followups):?><section class="mt-5 rounded-2xl border border-amber-200 bg-amber-50 p-5 shadow-sm"><div class="flex flex-wrap items-start justify-between gap-3"><div><h2 class="font-bold text-amber-950"><i class="fa-solid fa-user-clock mr-2"></i>กรณีไม่มีใบตอบรับ</h2><p class="mt-1 text-sm text-amber-900">เจ้าหน้าที่ตรวจยืนยันผลจากข้อมูลที่นักศึกษาแจ้งเองก่อนให้ระบบดำเนินการต่อ</p></div><span class="rounded-full bg-white px-3 py-1 text-sm font-bold text-amber-800"><?=count($followups)?> รายการ</span></div><div class="mt-4 grid gap-3 lg:grid-cols-2"><?php foreach($followups as $followup):?><article class="rounded-xl border border-amber-200 bg-white p-4"><p class="font-bold text-slate-900"><?=h($followup['student_number'].' '.trim(($followup['prefix_short']??'').$followup['firstname'].' '.$followup['lastname']))?></p><p class="mt-1 text-sm text-slate-600"><?=h($followup['company_name'])?> <span class="mx-1 text-slate-300">•</span><?=h($followup['group_name'])?></p><p class="mt-2 text-sm font-semibold text-amber-900"><?= $followup['reported_result']==='accepted'?'นักศึกษาแจ้งว่า: รับเข้าฝึกงาน':($followup['reported_result']==='not_accepted'?'นักศึกษาแจ้งว่า: ไม่รับเข้าฝึกงาน':'นักศึกษาแจ้งว่า: ยังไม่ทราบผล') ?></p><?php if($followup['student_note']):?><p class="mt-2 rounded-lg bg-amber-50 p-3 text-sm text-slate-700"><b>เหตุผล/ช่องทาง:</b> <?=h($followup['student_note'])?></p><?php endif;?><?php $noDocumentStatus=(string)($followup['no_document_review_status']??'');if($noDocumentStatus==='approved'):?><p class="mt-3 rounded-lg bg-emerald-50 p-3 text-sm font-bold text-emerald-800">เจ้าหน้าที่ยืนยันแล้ว — ใช้ดำเนินขั้นตอนใบส่งตัวได้</p><?php elseif($noDocumentStatus==='not_accepted'):?><p class="mt-3 rounded-lg bg-red-50 p-3 text-sm font-bold text-red-800">บันทึกว่าไม่รับเข้าฝึกงาน</p><?php elseif(!$isCoordinatorReviewer && responseNoDocumentReviewAvailable($pdo)):?><form method="post" class="mt-3 space-y-2 rounded-lg bg-slate-50 p-3"><?=csrf_field()?><input type="hidden" name="no_document_review" value="1"><input type="hidden" name="response_declaration_id" value="<?=(int)$followup['response_declaration_id']?>"><label><span class="block text-xs font-bold text-slate-700">วิธีตรวจสอบ / ข้อความถึงนักศึกษา *</span><input name="review_note" required class="mt-1 w-full rounded-lg border border-slate-300 px-3 py-2 text-sm" placeholder="เช่น โทรยืนยันกับบริษัท วันที่ …"></label><div class="flex flex-wrap gap-2"><button name="no_document_action" value="approve" class="rounded-lg bg-emerald-700 px-3 py-2 text-sm font-bold text-white">ยืนยันรับเข้าฝึกงาน</button><button name="no_document_action" value="revision" class="rounded-lg bg-amber-500 px-3 py-2 text-sm font-bold text-white">ขอข้อมูลเพิ่ม</button><button name="no_document_action" value="not_accepted" class="rounded-lg bg-red-700 px-3 py-2 text-sm font-bold text-white">ไม่รับ</button></div></form><?php elseif(!$isCoordinatorReviewer):?><p class="mt-3 text-sm text-red-700">ยังไม่ได้ติดตั้งส่วนตรวจยืนยันกรณีไม่มีใบตอบรับ</p><?php endif;?></article><?php endforeach;?></div></section><?php endif;?>
<section class="mt-5 overflow-hidden rounded-2xl border border-slate-200 bg-white shadow-sm"><div class="flex items-center justify-between border-b border-slate-100 px-5 py-4"><div><h2 class="font-bold">รายการหนังสือตอบรับ</h2><p class="text-sm text-slate-500">ตรวจสอบได้เฉพาะนักศึกษาในสาขาของคุณ</p></div><span class="rounded-full bg-slate-100 px-3 py-1 text-sm font-bold text-slate-600"><?= $total ?> รายการ</span></div><div class="divide-y divide-slate-100"><?php foreach($rows as $row):?><article class="p-5"><div class="flex flex-col gap-4 xl:flex-row xl:items-start xl:justify-between"><div class="min-w-0"><div class="flex flex-wrap items-center gap-2"><h3 class="font-bold text-slate-900"><?=h($row['student_number'].' '.trim(($row['prefix_short']??'').$row['firstname'].' '.$row['lastname']))?></h3><span class="rounded-full px-2.5 py-1 text-xs font-bold <?=$classes[$row['review_status']]?>"><?=$labels[$row['review_status']]?></span></div><p class="mt-1 text-sm text-slate-600"><?=h($row['group_name'])?> <span class="mx-1 text-slate-300">•</span><?=h($row['company_name'])?></p><p class="mt-2 text-xs text-slate-400">อัปโหลดเมื่อ <?=h(date('d/m/Y H:i น.',strtotime($row['uploaded_at'])))?></p><?php if($row['review_note']):?><p class="mt-3 rounded-lg bg-slate-50 p-3 text-sm text-slate-700"><b>หมายเหตุ:</b> <?=h($row['review_note'])?></p><?php endif;?></div><?php $responseExtension=strtolower(pathinfo((string)$row['original_filename'],PATHINFO_EXTENSION)); ?><a href="download_response_letter.php?id=<?=(int)$row['response_document_id']?>" data-response-extension="<?=h($responseExtension)?>" target="_blank" class="inline-flex shrink-0 items-center justify-center gap-2 rounded-xl border border-slate-300 bg-white px-4 py-2.5 font-bold text-slate-700 hover:border-red-300 hover:text-red-700"><i class="fa-solid <?=in_array($responseExtension,['doc','docx'],true)?'fa-file-word':'fa-file-pdf'?>"></i>ดูไฟล์</a></div><?php if($row['review_status']==='pending'):?><form method="post" class="mt-4 grid gap-3 rounded-xl bg-slate-50 p-4 lg:grid-cols-[minmax(0,1fr)_auto]"><?=csrf_field()?><input type="hidden" name="response_document_id" value="<?=(int)$row['response_document_id']?>"><label><span class="mb-1 block text-sm font-bold text-slate-700">ข้อความถึงนักศึกษา <span class="font-normal text-slate-400">(จำเป็นเมื่อส่งกลับหรือไม่รับ)</span></span><input name="review_note" class="w-full rounded-lg border border-slate-300 px-3 py-2.5" placeholder="ระบุจุดที่ต้องแก้ไข หรือเหตุผล"></label><div class="flex flex-wrap items-end gap-2"><button name="review_action" value="approve" class="rounded-xl bg-emerald-700 px-4 py-2.5 font-bold text-white"><i class="fa-solid fa-check mr-1"></i>ผ่าน</button><button name="review_action" value="revision" class="rounded-xl bg-amber-500 px-4 py-2.5 font-bold text-white"><i class="fa-solid fa-rotate-left mr-1"></i>ส่งกลับแก้ไข</button><button name="review_action" value="not_accepted" class="rounded-xl bg-red-700 px-4 py-2.5 font-bold text-white"><i class="fa-solid fa-xmark mr-1"></i>ไม่รับ</button></div></form><?php endif;?></article><?php endforeach;?><?php if(!$rows):?><div class="p-10 text-center text-slate-500">ไม่มีรายการตามสถานะที่เลือก</div><?php endif;?></div></section><?php render_pagination($total,$page,$perPage,'page');?></main></div><?php if(isset($_GET['reviewed'])):?><div hidden data-success-alert data-success-title="บันทึกผลการตรวจสอบแล้ว" data-success-clean-param="reviewed"></div><?php endif;?></body></html>
